def runs(I,v):
    H=len(I); W=len(I[0]); out=[]
    for r in range(H):
        c=0
        while c<W:
            if I[r][c]==v:
                s=c
                while c<W and I[r][c]==v: c+=1
                out.append((r,s,c-1,c-s+1))
            else: c+=1
    return out
